import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.CYjxsSA2.js";const p=JSON.parse('{"title":"errcli 命令行","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/errcli.md","filePath":"advanced/errcli.md"}'),o={name:"advanced/errcli.md"};function c(l,t,i,n,s,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="errcli-命令行" tabindex="-1">errcli 命令行 <a class="header-anchor" href="#errcli-命令行" aria-label="Permalink to &quot;errcli 命令行&quot;">​</a></h1><p>VAELOR 随包附带一个命令行工具 <code>errcli</code>，用于管理<strong>反向会话</strong>（拿到 Shell 后的稳定通道）。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>errcli daemon</code></td><td>启动后台守护进程</td></tr><tr><td><code>errcli rev</code></td><td>开一个反向会话监听</td></tr><tr><td><code>errcli list</code></td><td>查看当前会话</td></tr><tr><td><code>errcli stop</code></td><td>停止指定会话</td></tr><tr><td><code>errcli restart</code></td><td>重启会话</td></tr></tbody></table><p>启动监听后，把工具生成的 Payload 复制到目标上执行即可建立会话。各子命令的具体参数以 <code>errcli -h</code> 的提示为准。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>对公网目标，要确保 Payload 里的<strong>回连地址</strong>是公网可达的，否则目标连不回来</li><li>会话依赖长连接，链路上有代理时注意不要被中途切断</li><li>反向会话属高危动作，军团触发时会弹出人工确认</li></ul>',7)])])}const m=e(o,[["render",c]]);export{p as __pageData,m as default};
